export const postInstanceInstanceIdReplicateRoute = createRoute({
  method: 'post',
  path: '/instance/{InstanceId}/replicate',
  description:
    '<p>Replicates an Amazon Connect instance in the specified Amazon Web Services Region.</p> <p>For more information about replicating an Amazon Connect instance, see <a href="https://docs.aws.amazon.com/connect/latest/adminguide/create-replica-connect-instance.html">Create a replica of your existing Amazon Connect instance</a> in the <i>Amazon Connect Administrator Guide</i>.</p>',
  operationId: 'ReplicateInstance',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    params: z.object({
      InstanceId: z
        .string()
        .regex(
          /^(arn:(aws|aws-us-gov):connect:[a-z]{2}-[a-z]+-[0-9]{1}:[0-9]{1,20}:instance\/)?[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/,
        )
        .min(1)
        .max(250)
        .openapi({
          param: {
            name: 'InstanceId',
            in: 'path',
            required: true,
            description:
              'The identifier of the Amazon Connect instance. You can <a href="https://docs.aws.amazon.com/connect/latest/adminguide/find-instance-arn.html">find the instance ID</a> in the Amazon Resource Name (ARN) of the instance. You can provide the <code>InstanceId</code>, or the entire ARN.',
            schema: {
              type: 'string',
              pattern:
                '^(arn:(aws|aws-us-gov):connect:[a-z]{2}-[a-z]+-[0-9]{1}:[0-9]{1,20}:instance/)?[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$',
              minLength: 1,
              maxLength: 250,
            },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              ReplicaRegion: z
                .string()
                .regex(/[a-z]{2}(-[a-z]+){1,2}(-[0-9])?/)
                .min(8)
                .max(31)
                .openapi({
                  description:
                    'The Amazon Web Services Region where to replicate the Amazon Connect instance.',
                }),
              ClientToken: z
                .string()
                .max(500)
                .exactOptional()
                .openapi({
                  description:
                    'A unique, case-sensitive identifier that you provide to ensure the idempotency of the request. If not provided, the Amazon Web Services SDK populates this field. For more information about idempotency, see <a href="https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/">Making retries safe with idempotent APIs</a>.',
                }),
              ReplicaAlias: z
                .string()
                .regex(/^(?!d-)([\da-zA-Z]+)([-]*[\da-zA-Z])*$/)
                .min(1)
                .max(45)
                .openapi({
                  description:
                    'The alias for the replicated instance. The <code>ReplicaAlias</code> must be unique.',
                }),
            })
            .openapi({ required: ['ReplicaRegion', 'ReplicaAlias'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ReplicateInstanceResponseSchema } },
    },
    480: {
      description: 'InvalidRequestException',
      content: { 'application/json': { schema: InvalidRequestExceptionSchema } },
    },
    481: {
      description: 'AccessDeniedException',
      content: { 'application/json': { schema: AccessDeniedExceptionSchema } },
    },
    482: {
      description: 'ServiceQuotaExceededException',
      content: { 'application/json': { schema: ServiceQuotaExceededExceptionSchema } },
    },
    483: {
      description: 'ThrottlingException',
      content: { 'application/json': { schema: ThrottlingExceptionSchema } },
    },
    484: {
      description: 'ResourceNotFoundException',
      content: { 'application/json': { schema: ResourceNotFoundExceptionSchema } },
    },
    485: {
      description: 'InternalServiceException',
      content: { 'application/json': { schema: InternalServiceExceptionSchema } },
    },
    486: {
      description: 'ResourceNotReadyException',
      content: { 'application/json': { schema: ResourceNotReadyExceptionSchema } },
    },
    487: {
      description: 'ResourceConflictException',
      content: { 'application/json': { schema: ResourceConflictExceptionSchema } },
    },
  },
})

